"use client";
import { useState } from "react";

const products = ["Coca-Cola", "Bread", "Rice 5kg", "Milk", "Biscuits", "Water"];
export default function SalesPage(){const [cart,setCart]=useState<string[]>([]);const [method,setMethod]=useState("cash");return <main className="min-h-screen bg-[#0b0b0b] p-5 text-white md:p-8"><div className="mx-auto max-w-7xl"><div className="mb-7 flex items-center justify-between"><div><p className="text-xl font-bold">TX <span className="text-orange-500">RetailOS</span></p><h1 className="mt-4 text-2xl font-semibold">Sales</h1></div><a href="/employee-dashboard" className="text-sm text-white/50 hover:text-white">Dashboard</a></div><div className="grid gap-6 lg:grid-cols-[1fr_360px]"><section className="rounded-2xl border border-white/10 bg-[#151515] p-5"><div className="mb-5 flex items-center justify-between"><h2 className="font-semibold">Products</h2><span className="text-sm text-white/40">{products.length} items</span></div><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">{products.map((name,i)=><article key={name} className="rounded-xl border border-white/10 bg-[#101010] p-4"><div className="mb-8 h-24 rounded-lg bg-white/5"/><h3 className="font-medium">{name}</h3><p className="mt-1 text-orange-400">₦{(1500+i*750).toLocaleString()}</p><p className="mt-1 text-xs text-white/40">{i===5?0:10+i} in stock</p><button onClick={()=>setCart(c=>[...c,name])} className="mt-4 w-full rounded-lg bg-orange-500 px-3 py-2 text-sm font-semibold text-black hover:bg-orange-400">Add to cart</button></article>)}</div></section><aside className="h-fit rounded-2xl border border-white/10 bg-[#151515] p-5"><h2 className="mb-5 font-semibold">Cart</h2><div className="min-h-32 space-y-2">{cart.length?cart.map((x,i)=><div key={`${x}-${i}`} className="flex justify-between rounded-lg bg-white/5 px-3 py-2 text-sm"><span>{x}</span><span>₦{(1500+i*750).toLocaleString()}</span></div>):<p className="py-8 text-center text-sm text-white/30">Cart is empty</p>}</div><div className="my-5 flex justify-between border-t border-white/10 pt-4"><span>Total</span><strong>₦{cart.reduce((s,_,i)=>s+1500+i*750,0).toLocaleString()}</strong></div><p className="mb-2 text-xs text-white/40">Payment Method</p><div className="grid grid-cols-3 gap-2">{["cash","transfer","pos"].map(x=><button key={x} onClick={()=>setMethod(x)} className={`rounded-lg px-2 py-2 text-xs capitalize ${method===x?"bg-orange-500 text-black":"bg-white/5 text-white/60"}`}>{x}</button>)}</div><button className="mt-4 w-full rounded-xl bg-orange-500 py-3 font-semibold text-black hover:bg-orange-400">Complete Sale</button></aside></div></div></main>}
